fn scale(m: Money, factor: Decimal) -> Money {            // query: owns its input, returns a value
    Money { amount: m.amount * factor, ..m }
}

fn total(lines: &[Line]) -> Decimal {                     // query: cannot mutate the caller's data
    lines.iter().map(|l| l.price.amount * l.qty).sum()
}

impl Account {
    fn deposit(&mut self, m: Money) { self.balance += m.amount; }   // command
}
